import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 7.8
.target sm_89
.address_size 64

// Specialized ConvTranspose3d kernel for:
// x:      (16, 32, 16, 32, 64)  float32
// weight: (32, 16, 3, 5, 7)     float32  (in_channels, out_channels, kD, kH, kW)
// out:    (16, 16, 18, 36, 70)  float32
// stride=(1,1,1) padding=(0,0,0) output_padding=(0,0,0) groups=1 bias=False

.visible .entry conv_transpose3d_kernel(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 out_ptr,
    .param .u32 total_elements
)
{
    .reg .b32 %r<80>;
    .reg .b64 %rd<40>;
    .reg .f32 %f<10>;
    .reg .pred %p<20>;

    ld.param.u64 %rd1, [x_ptr];
    ld.param.u64 %rd2, [w_ptr];
    ld.param.u64 %rd3, [out_ptr];
    ld.param.u32 %r1, [total_elements];

    cvta.to.global.u64 %rd1, %rd1;
    cvta.to.global.u64 %rd2, %rd2;
    cvta.to.global.u64 %rd3, %rd3;

    mov.u32 %r2, %ctaid.x;
    mov.u32 %r3, %ntid.x;
    mov.u32 %r4, %tid.x;
    mad.lo.u32 %r5, %r2, %r3, %r4;   // idx

    setp.ge.u32 %p1, %r5, %r1;
    @%p1 bra DONE;

    // decompose idx using output strides
    div.u32 %r11, %r5, 70;    // t1 = idx / 70
    rem.u32 %r12, %r5, 70;    // ow
    div.u32 %r13, %r11, 36;   // t2 = t1 / 36
    rem.u32 %r14, %r11, 36;   // oh
    div.u32 %r15, %r13, 18;   // t3 = t2 / 18
    rem.u32 %r16, %r13, 18;   // od
    div.u32 %r17, %r15, 16;   // b
    rem.u32 %r18, %r15, 16;   // oc

    mov.f32 %f1, 0f00000000;

    mov.u32 %r20, 0; // ic
LOOP_IC:
    setp.ge.u32 %p2, %r20, 32;
    @%p2 bra END_IC;

    mov.u32 %r21, 0; // kd
LOOP_KD:
    setp.ge.u32 %p3, %r21, 3;
    @%p3 bra END_KD;

    sub.s32 %r22, %r16, %r21;        // id
    setp.lt.s32 %p4, %r22, 0;
    setp.ge.s32 %p5, %r22, 16;
    or.pred %p6, %p4, %p5;
    @%p6 bra INC_KD;

    mov.u32 %r23, 0; // kh
LOOP_KH:
    setp.ge.u32 %p7, %r23, 5;
    @%p7 bra END_KH;

    sub.s32 %r24, %r14, %r23;        // ih
    setp.lt.s32 %p8, %r24, 0;
    setp.ge.s32 %p9, %r24, 32;
    or.pred %p10, %p8, %p9;
    @%p10 bra INC_KH;

    mov.u32 %r25, 0; // kw
LOOP_KW:
    setp.ge.u32 %p11, %r25, 7;
    @%p11 bra END_KW;

    sub.s32 %r26, %r12, %r25;        // iw
    setp.lt.s32 %p12, %r26, 0;
    setp.ge.s32 %p13, %r26, 64;
    or.pred %p14, %p12, %p13;
    @%p14 bra INC_KW;

    // x offset = b*1048576 + ic*32768 + id*2048 + ih*64 + iw
    mul.lo.u32 %r30, %r17, 1048576;
    mul.lo.u32 %r31, %r20, 32768;
    add.u32 %r30, %r30, %r31;
    mul.lo.u32 %r31, %r22, 2048;
    add.u32 %r30, %r30, %r31;
    mul.lo.u32 %r31, %r24, 64;
    add.u32 %r30, %r30, %r31;
    add.u32 %r30, %r30, %r26;

    mul.wide.u32 %rd11, %r30, 4;
    add.u64 %rd12, %rd1, %rd11;
    ld.global.f32 %f2, [%rd12];

    // weight offset = ic*1680 + oc*105 + kd*35 + kh*7 + kw
    mul.lo.u32 %r32, %r20, 1680;
    mul.lo.u32 %r33, %r18, 105;
    add.u32 %r32, %r32, %r33;
    mul.lo.u32 %r33, %r21, 35;
    add.u32 %r32, %r32, %r33;
    mul.lo.u32 %r33, %r23, 7;
    add.u32 %r32, %r32, %r33;
    add.u32 %r32, %r32, %r25;

    mul.wide.u32 %rd13, %r32, 4;
    add.u64 %rd14, %rd2, %rd13;
    ld.global.f32 %f3, [%rd14];

    fma.rn.f32 %f1, %f2, %f3, %f1;

INC_KW:
    add.u32 %r25, %r25, 1;
    bra LOOP_KW;
END_KW:

INC_KH:
    add.u32 %r23, %r23, 1;
    bra LOOP_KH;
END_KH:

INC_KD:
    add.u32 %r21, %r21, 1;
    bra LOOP_KD;
END_KD:

    add.u32 %r20, %r20, 1;
    bra LOOP_IC;
END_IC:

    mul.wide.u32 %rd20, %r5, 4;
    add.u64 %rd21, %rd3, %rd20;
    st.global.f32 [%rd21], %f1;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("conv_transpose3d_kernel")

class ModelNew(nn.Module):
    def __init__(self, in_channels: int, out_channels: int, kernel_size: tuple,
                 stride: tuple = (1, 1, 1), padding: tuple = (0, 0, 0),
                 output_padding: tuple = (0, 0, 0), groups: int = 1, bias: bool = False):
        super(ModelNew, self).__init__()
        self.conv_transpose3d = nn.ConvTranspose3d(
            in_channels, out_channels, kernel_size,
            stride=stride, padding=padding, output_padding=output_padding,
            groups=groups, bias=bias
        )

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        x = x.contiguous()
        weight = self.conv_transpose3d.weight.contiguous()

        B, C_in, D_in, H_in, W_in = x.shape
        out_channels = self.conv_transpose3d.out_channels
        kD, kH, kW = self.conv_transpose3d.kernel_size
        sD, sH, sW = self.conv_transpose3d.stride
        pD, pH, pW = self.conv_transpose3d.padding
        opD, opH, opW = self.conv_transpose3d.output_padding

        D_out = (D_in - 1) * sD - 2 * pD + kD + opD
        H_out = (H_in - 1) * sH - 2 * pH + kH + opH
        W_out = (W_in - 1) * sW - 2 * pW + kW + opW

        output = torch.empty(
            (B, out_channels, D_out, H_out, W_out),
            dtype=x.dtype, device=x.device
        )

        total = output.numel()
        module = _get_ptx_module()

        block = 256
        grid = (total + block - 1) // block

        module.launch(
            "conv_transpose3d_kernel",
            grid=(grid, 1, 1),
            block=(block, 1, 1),
            arguments=[x, weight, output, i32(total)],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )

        return output

